        return None
    if b.turn == chess.WHITE:
        # White to move: find a move that mates in n-1 for Black's replies
        for m in b.legal_moves:
            b.push(m)
            ok = True
            line = [m.uci()]
            if b.is_checkmate():
                b.pop(); return line
            if n-1 > 0:
                # Black must have NO escape
                sub = None
                allbad = True
                for r in b.legal_moves:
                    b.push(r)
                    res = mate_in(b, n-1)
                    b.pop()
                    if res is None:
                        allbad = False; break
                    sub = res
                if allbad and b.legal_moves:
                    b.pop(); return line + ['...']
            b.pop()
        return None
    return None

def white_forces_mate(b, plies):
    """exhaustive: White to move, can White mate within `plies` half-moves?"""
    if b.is_checkmate(): return True
    if plies <= 0: return False
    if b.turn == chess.WHITE:
        for m in b.legal_moves:
            b.push(m)
            if white_forces_mate(b, plies-1):
                b.pop(); return True
            b.pop()
        return False
    else:
        if not b.legal_moves: return False
        for m in b.legal_moves:
            b.push(m)
            if not white_forces_mate(b, plies-1):
                b.pop(); return False
            b.pop()
        return True

